INSERT INTO "agnes_video_tasks" ("id", "task_id", "api_key_id", "created_at", "updated_at", "owner_key", "owner_role", "owner_name", "model", "prompt", "status", "progress", "video_url", "seconds", "last_error", "is_public", "public_at") VALUES (213, 'task_XC0nanWBY7LVLZvQ0BeiA7LTRC0XnOWH', 1, '2026-06-01T15:42:25.106829+00:00', '2026-06-01T15:46:29.631964+00:00', 'guest:127.0.0.1', 'guest', 'guest', 'agnes-video-v2.0', '电影级品牌概念视频，强节奏bgm驱动，快切蒙太奇+慢动作+微距+延时摄影结合，极具震撼感、速度感与科技感。整体无对白，仅鼓点节拍、低频心跳、呼吸声、水声与环境声。0～4秒，肉眼难以看到的微观与隐藏世界，极致微距与时间操控质感：超微距水滴落下瞬间爆裂成皇冠水花，参考@视频1前半部分；雪花冰晶向外蔓延生长；花粉在空气中漂浮形成粒子轨迹；蝴蝶振翅鳞粉飞散慢动作，伴随振翅声音；声波震动音箱表面细沙跳动；星轨旋转与云层翻滚延时摄影；海水下气泡上升，光束穿透海水画面。5～12秒，节拍突然加强，所有动作与音乐完全同步：羚羊跨过山涧远景慢动作；自由泳高速划水，水花炸裂；专业潜水员在海底与鲸和鱼群共舞；攀岩抓点发力，镁粉粉尘爆散；滑雪或滑板高速掠过，雪雾/碎石飞起；海豚跃出水面鸣叫，水花在空中冻结慢动作；户外山地自行车冲坡腾空，落地震动扬土；鸟群与鱼群集体转向形成流线波浪，世界仿佛在节拍中跳跃、呼吸、爆发。闪黑。13～15秒，突然出现极致微距婴儿人眼特写，眼睛突然睁开，柔和电影光。声音只剩心跳。黑场。中央极简白字：KFC。', 'completed', 100, 'https://storage.googleapis.com/agnes-aigc/aigc/videos/2026/06/01/video_f8a6122c0f9bd8f7d364336a9e8b63576d998a4e9e2e9eaf.mp4', '5.0', '', 0, NULL);
